// PRODUCER (API Endpoint):
app.post('/api/orders', async (req, res) => {
  const order = await saveOrderToDB(req.body);
  // Push event to queue and return 202 Accepted immediately!
  await queue.send('order-created-queue', { orderId: order.id });
  res.status(202).json({ status: 'Order queued for processing' });
});

// WORKER (Background Process):
queue.consume('order-created-queue', async (msg) => {
  try {
    await processOrderPayment(msg.orderId);
    queue.ack(msg); // Acknowledge message removal!
  } catch (err) {
    queue.nack(msg, false, false); // Send to Dead-Letter Queue (DLQ)
  }
});

class QueueNode<T> {
  value: T; next: QueueNode<T> | null = null;
  constructor(val: T) { this.value = val; }
}

export class Queue<T> {
  private head: QueueNode<T> | null = null;
  private tail: QueueNode<T> | null = null;

  enqueue(val: T): void {
    const node = new QueueNode(val);
    if (this.tail) this.tail.next = node;
    this.tail = node;
    if (!this.head) this.head = node;
  }

  dequeue(): T | null {
    if (!this.head) return null;
    const val = this.head.value;
    this.head = this.head.next;
    if (!this.head) this.tail = null;
    return val;
  }
}

async function getProduct(productId) {
  const cacheKey = `product:${productId}`;

  // 1. Check Redis Cache
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached); // Cache Hit!

  // 2. Cache Miss: Query Database
  const product = await db.findProduct(productId);

  if (product) {
    // 3. Write to Redis with 10m TTL
    await redis.set(cacheKey, JSON.stringify(product), 'EX', 600);
  } else {
    // Prevent Cache Penetration: Cache null for 1m
    await redis.set(cacheKey, 'null', 'EX', 60);
  }

  return product;
}

http {
  # Upstream pool of application backend servers
  upstream app_cluster {
    least_conn; # Route to server with fewest active connections!
    server 10.0.0.1:4000 max_fails=3 fail_timeout=10s;
    server 10.0.0.2:4000 max_fails=3 fail_timeout=10s;
    server 10.0.0.3:4000 backup; # Fallback server
  }

  server {
    listen 80;
    location / {
      proxy_pass http://app_cluster;
      proxy_set_header Host $host;
    }
  }
}

import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

const s3 = new S3Client({ region: 'us-east-1' });

export async function generateUploadUrl(filename: string, fileType: string) {
  const key = `uploads/${Date.now()}-${filename}`;
  const command = new PutObjectCommand({
    Bucket: 'my-app-storage',
    Key: key,
    ContentType: fileType
  });

  // Generates 15-minute valid presigned PUT URL
  const uploadUrl = await getSignedUrl(s3, command, { expiresIn: 900 });
  return { uploadUrl, key };
}

import sharp from 'sharp';
import fs from 'fs/promises';

export async function processAvatarJob(inputBuffer: Buffer): Promise<Buffer> {
  // Resize to 300x300 and convert to efficient WebP format
  const processedBuffer = await sharp(inputBuffer)
    .resize(300, 300, { fit: 'cover' })
    .webp({ quality: 80 })
    .toBuffer();

  return processedBuffer;
}

import { Queue, Worker } from 'bullmq';
const connection = { host: 'localhost', port: 6379 };

// 1. PRODUCER: Enqueue job with exponential backoff retry options
const emailQueue = new Queue('emailQueue', { connection });
await emailQueue.add('sendWelcomeEmail', 
  { email: 'user@example.com' },
  { attempts: 5, backoff: { type: 'exponential', delay: 1000 } }
);

// 2. WORKER: Process jobs in background worker pool
const worker = new Worker('emailQueue', async job => {
  console.log(`Processing job ${job.id} for ${job.data.email}`);
  await sendEmail(job.data.email);
}, { connection });
